      ACCEPT_TOKEN(anon_sym_override);
      END_STATE();
    case 340:
      if (lookahead == 'd') ADVANCE(348);
      END_STATE();
    case 341:
      ACCEPT_TOKEN(anon_sym_readonly);
      END_STATE();
    case 342:
      if (lookahead == 's') ADVANCE(349);
      END_STATE();
    case 343:
      if (lookahead == 'd') ADVANCE(350);
      END_STATE();
    case 344:
